package net.officefloor.hq.app.plan;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.claim.ClaimRequest;
import net.officefloor.hq.app.claim.ClaimValues;
import net.officefloor.hq.app.claim.InvalidClaimException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the amount is one the claim form takes for a claim that corrects nothing (a number 0.00 or more
 *  with up to two decimals, see ClaimValues); the start and end are yyyy-MM-dd, the end not before the start; every N
 *  days is a whole number, at least 1 — or, instead, a day of the month is a whole number from 1 to 31 (not both). */
public class ValidatePlan {
    public void validate(@RequestBody PlanRequest request, Out<PlanValues> values) throws InvalidPlanException {
        if (request == null) {
            throw new InvalidPlanException("A plan is required");
        }
        ClaimValues claim;
        try {
            claim = ClaimValues.from(new ClaimRequest(request.amount(), null, "", null, request.by(), null, null));
        } catch (InvalidClaimException e) {
            throw new InvalidPlanException(e.getMessage());
        }
        if (claim.amount().signum() < 0) {
            throw new InvalidPlanException("A plan's amount must be 0.00 or more");
        }
        LocalDate start = date(request.start(), "start");
        LocalDate end = date(request.end(), "end");
        if (end.isBefore(start)) {
            throw new InvalidPlanException("A plan's end must not be before its start");
        }
        String every = request.every() == null ? "" : request.every().trim();
        String day = request.day() == null ? "" : request.day().trim();
        if (!day.isEmpty()) {
            if (!every.isEmpty()) {
                throw new InvalidPlanException("A plan runs every N days or on a day of the month, not both");
            }
            if (!day.matches("\\d{1,2}") || Integer.parseInt(day) < 1 || Integer.parseInt(day) > 31) {
                throw new InvalidPlanException("A plan's day of the month must be a whole number from 1 to 31");
            }
            values.set(new PlanValues(claim.amount(), start, null, Integer.parseInt(day), end, claim.by()));
            return;
        }
        if (!every.matches("\\d{1,6}") || Integer.parseInt(every) < 1) {
            throw new InvalidPlanException("A plan's interval must be a whole number of days, at least 1");
        }
        values.set(new PlanValues(claim.amount(), start, Integer.parseInt(every), null, end, claim.by()));
    }

    private static LocalDate date(String typed, String what) throws InvalidPlanException {
        try {
            return LocalDate.parse(typed == null ? "" : typed.trim());
        } catch (DateTimeParseException e) {
            throw new InvalidPlanException("A plan's " + what + " must be yyyy-MM-dd");
        }
    }
}
package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.stream.Collectors;

/** A plan as listed: the plan and its next dates — its first five dates after the sheet's today and on or before its
 *  end (see PlanDates), comma and space separated — whether it is paused, and its changes of amount, oldest first,
 *  each as {@code <date> amount=<amount>}. */
public record PlanView(long id, long personId, BigDecimal amount, LocalDate start, Integer every, Integer day,
        LocalDate end, int generated, String nextDates, boolean paused, List<String> changes) {

    public static PlanView of(Plan plan, LocalDate today) {
        String next = PlanDates.after(plan, today, 5).stream().map(LocalDate::toString)
                .collect(Collectors.joining(", "));
        return new PlanView(plan.id(), plan.personId(), plan.amount(), plan.start(), plan.every(), plan.day(),
                plan.end(), plan.generated(), next, plan.paused(),
                plan.changes().stream().map((c) -> c.date() + " amount=" + c.amount().toPlainString()).toList());
    }
}
# POST /api/sheets/{sheetId}/people/{personId}/plans — add a plan to a person: an amount the claim form takes for a
# claim that corrects nothing, a start and an end date (yyyy-MM-dd, the end not before the start) and every N days (a
# whole number, at least 1) or, instead, a day of the month (a whole number from 1 to 31; not both). Any other is a 400, a person not on the sheet a 404, none writing anything. Writes
# PLAN_ADDED. Responds 201 with the plan.
